import {safeLink} from '../../src/rules.js'
import {marketplaceSeed} from '../../src/marketplace.js'
const key='sisu-community-v1'
export function community(){try{const saved=JSON.parse(localStorage.getItem(key));if(saved)return saved}catch{}const source=marketplaceSeed();return {profiles:source.providers.map(p=>({...p,display_name:p.title,kind:p.type==='Institute'?'Institute':'Teacher',status:'Verified',user:p.owner||p.name,code:p.name==='teen-academy'?'TA0000500':p.code})),links:[],pending:[{name:'demo-pending-academy',username:'violetacademy',display_name:'Violet Learning Academy · Demo',kind:'Institute',country:'United Kingdom',user:'demo-owner@example.invalid',status:'Pending'}],serial:501}}
export function storeCommunity(data){localStorage.setItem(key,JSON.stringify(data));window.dispatchEvent(new Event('sisu-community'))}
export function createProfile(data){const c=community(),username=String(data.username||'').trim().toLowerCase();if(!String(data.display_name||'').trim()||!data.country||!['Student','Teacher','Institute'].includes(data.kind))throw Error('Name, country and a valid profile type are required.');if(!/^[a-z][a-z0-9_]{2,29}$/.test(username)||['admin','sisu','support','owner'].includes(username))throw Error('Choose a unique 3–30 character username using letters, digits or underscores.');if([...c.profiles,...c.pending].some(p=>p.username===username&&p.user!==data.user))throw Error('That username is already taken.');const previous=[...c.profiles,...c.pending].find(p=>p.user===data.user);if(previous&&previous.username!==username)throw Error('One permanent username per user.');const profile={...data,username,name:previous?.name||crypto.randomUUID(),title:data.display_name,type:data.kind==='Institute'?'Institute':'Independent teacher',status:data.kind==='Student'?'Verified':'Pending',code:previous?.code||'',color:'#e8def7',symbol:data.display_name.slice(0,2),bio:data.bio||'',socials:data.socials||{}};c.pending=c.pending.filter(p=>p.user!==data.user);c.profiles=c.profiles.filter(p=>p.user!==data.user);(data.kind==='Student'?c.profiles:c.pending).push(profile);storeCommunity(c);return profile}
export function approveProfile(name,decision){const c=community(),p=c.pending.find(p=>p.name===name);if(!p)throw Error('Profile request unavailable');p.status=decision;if(decision==='Verified'){const words=p.display_name.match(/[A-Za-z]+/g)||['Education'];p.code=words.slice(0,2).map(w=>w[0]).join('').toUpperCase().padEnd(2,'X')+String(c.serial++).padStart(7,'0');c.profiles.push(p);c.pending=c.pending.filter(x=>x.name!==name)}storeCommunity(c);return p}
export function relationship(profile,user,kind){const c=community();let link=c.links.find(l=>l.profile===profile&&l.user===user&&l.kind===kind);if(link&&['Active','Pending'].includes(link.status))return link;if(!link){link={name:crypto.randomUUID(),profile,user,kind};c.links.push(link)}link.status=kind==='Follow'?'Active':'Pending';storeCommunity(c);return link}
export function changeLink(name,status){const c=community(),l=c.links.find(l=>l.name===name);if(l){l.status=status;storeCommunity(c)}}
